INSERT INTO products (name, slug, brand_id, description, dimensions, materials, source_url, image_url, category, created_at, updated_at) SELECT 'Ambit Pendant Cluster', 'ambit-pendant-cluster', b.id, 'The Ambit Cluster Pendant expands the timeless character of the Ambit Pendant Lamp into a refined multi-light composition. Crafted from aluminum with clean lines and a white interior, each shade enhances the light while creating a striking contrast with its exterior. Suspended together in a considered arrangement, the lamps form a balanced and architectural lighting feature suited to any space. Color: Black Variant: White / Black New item no.: AMBCL25A0101 Diameter: 76,00 cm / 29.20 in Colli: 1 Download product fact sheet: -                                     Product fact sheet', 'Diameter: 76,00 cm', 'The lampshade is made from press-spun aluminum. Colored versions are polished and wet-painted, while the Brushed Aluminum version is brushed and lacquered. The cord is made from extruded PVC, and the canopy is made from injection-molded ABS. The Brushed Aluminum EU version is designed for disassembly.  The canopy is made from injection-moulded ABS with steel brackets. The cross bracket is fitted with a hinge, allowing the canopy to be opened, adjusted, and closed to facilitate installation and adjustment of the lamp lengths.  The canopy is equipped with a strain relief and a connecting termina', 'https://www.muuto.com/product/Ambit-Pendant-Cluster/', 'https://cdn.occtoo-media.com/4d81f22f-2795-41f2-b8bf-15e9abf03890/cf649261-cc71-5d19-a0bb-37349e5c1cc0/Ambit-Cluster-6-Layout-1-Ring-Black-org.webp', 'other', NOW(), NOW() FROM brands b WHERE b.slug='muuto' ON CONFLICT DO NOTHING;
INSERT INTO products (name, slug, brand_id, description, dimensions, materials, source_url, image_url, category, created_at, updated_at) SELECT 'Brink Chair A-Base', 'brink-chair-a-base', b.id, 'Brink pairs a slim silhouette with surprising strength, developed through years of veneer refinement. The shell is crafted in form-pressed veneer made using FSC™-certified (FSC-C028824) wood. A distinctive bend reinforces the structure while softened edges support the body. Set on a polished aluminum or powder-coated A Base, it stacks efficiently for conference and contract settings. Brink is available in non-upholstered, seat-upholstered, or full-front-upholstered versions. The pads are removable. Only the non-upholstered and seat-upholstered versions are suitable for stacking. Shell Color: Black Upholstery: Refine Leather - Black Base Color: Black Linking Device Option: Standard Chair Glides: Felt Color: Black Variant: Black,Refine Leather - Black,Black,Standard Chair, Base material: A-Base Seat finish: Refine Leather - Black New item no.: BRCHABF01RA170112 Height: 82,30 cm / 32.40 in Width: 52,00 cm / 20.47 in Depth: 55,20 cm / 21.73 in Seat height: 46,20 cm / 18.19 in Seat depth: 4', 'Height: 82,30 cm; Width: 52,00 cm; Depth: 55,20 cm; height: 46,20 cm; depth: 40,00 cm', 'The shell is made from form-pressed veneer with a core of beech veneer layers and an oak surface veneer, made from FSC™-certified (FSC-C028824) wood. The surface is finished with a water-based lacquer. The chair is available in non-upholstered, with seat upholstery, or with front upholstery. Upholstery pads for both the seat and front are removable.  The A-base is made from powder-coated or polished aluminum, produced using 72% post-industrial recycled aluminum. Plastic glides are pre-mounted, w', 'https://www.muuto.com/product/Brink-Chair-A-Base/', 'https://cdn.occtoo-media.com/4d81f22f-2795-41f2-b8bf-15e9abf03890/0a286e63-7718-53a1-b364-56110228079a/brink-chair-a-base-dark-olive-folded-trolley-linear-system-config-1-oak-screen-table-lamp-pendant-lamp-high-res.webp?format=xl', 'chairs', NOW(), NOW() FROM brands b WHERE b.slug='muuto' ON CONFLICT DO NOTHING;
INSERT INTO products (name, slug, brand_id, description, dimensions, materials, source_url, image_url, category, created_at, updated_at) SELECT 'Brink Chair Cantilever Base', 'brink-chair-cantilever-base', b.id, 'Brink pairs a slim silhouette with surprising strength, developed through years of veneer refinement. The shell is crafted in form-pressed veneer made using FSC™-certified (FSC-C028824) wood. A distinctive bend reinforces the structure while softened edges support the body. Set on a chrome or powder-coated cantilever base, the chair introduces controlled flex in both frame and shell, enhancing comfort through natural movement while maintaining a precise, graphic expression. Brink is available in non-upholstered, seat-upholstered, or full-front-upholstered versions. The pads are removable. Color: Black Variant: Black / Black Base material: Cantilever Base Seat finish: No Upholstery New item no.: BRCHCAN01011 Height: 83,10 cm / 32.72 in Width: 48,00 cm / 18.90 in Depth: 54,70 cm / 21.54 in Seat height: 46,20 cm / 18.19 in Seat depth: 40,00 cm / 15.75 in Colli: 1 Download product fact sheet: -                                     Product fact sheet', 'Height: 83,10 cm; Width: 48,00 cm; Depth: 54,70 cm; height: 46,20 cm; depth: 40,00 cm', 'The shell is made from form-pressed veneer with a core of beech veneer layers and an oak surface veneer, made from FSC™-certified (FSC-C028824) wood. The surface is finished with a water-based lacquer. The chair is available in non-upholstered, with seat upholstery, or with front upholstery. Upholstery pads for both the seat and front are removable.  The cantilever base is made from powder-coated or chromed bent steel tube, produced using a minimum of 25% post-industrial recycled steel. Glides are pre-mounted and can be used as either felt or plastic by simply flipping them.  The chair can be ', 'https://www.muuto.com/product/Brink-Chair-Cantilever-Base/', 'https://cdn.occtoo-media.com/4d81f22f-2795-41f2-b8bf-15e9abf03890/cf8379b0-fb94-5e4d-adff-745d1efd437b/Brink-chair-cantilever-base-black-black-muuto-5000x5000-hi-res.webp', 'other', NOW(), NOW() FROM brands b WHERE b.slug='muuto' ON CONFLICT DO NOTHING;
INSERT INTO products (name, slug, brand_id, description, dimensions, materials, source_url, image_url, category, created_at, updated_at) SELECT 'Brink Chair Wood Base', 'brink-chair-wood-base', b.id, 'Brink pairs a slim silhouette with surprising strength, developed through years of veneer refinement. The shell is crafted in form-pressed veneer made using FSC™-certified (FSC-C028824) wood. A distinctive bend reinforces the structure while softened edges support the body. Set on a plywood base, the chair forms a unified wooden expression. Brink is available in non-upholstered, seat-upholstered, or full-front-upholstered versions. The pads are removable. Color: Black Variant: Black / Black Base material: Wood Base Seat finish: No Upholstery New item no.: BRCHWON01011 Height: 82,00 cm / 32.28 in Width: 46,00 cm / 18.11 in Depth: 54,50 cm / 21.46 in Seat height: 45,00 cm / 17.72 in Seat depth: 40,00 cm / 15.75 in Colli: 1 Download product fact sheet: -                                     Product fact sheet', 'Height: 82,00 cm; Width: 46,00 cm; Depth: 54,50 cm; height: 45,00 cm; depth: 40,00 cm', 'The shell is made from form-pressed veneer with a core of beech veneer layers and an oak surface veneer, made from FSC™-certified (FSC-C028824) wood. The surface is finished with a water-based lacquer. The chair is available in non-upholstered, with seat upholstery, or with front upholstery. Upholstery pads for both the seat and front are removable.  The legs are conically pressed, with a core of peeled beech veneers and an outer layer of oak veneer. The base is finished with water-based lacquer for all colors. Plastic glides are pre-mounted, with felt glides available as a spare part.  The ch', 'https://www.muuto.com/product/Brink-Chair-Wood-Base/', 'https://cdn.occtoo-media.com/4d81f22f-2795-41f2-b8bf-15e9abf03890/581ec7fa-0699-58ef-9172-a15cbe867977/Brink-chair-wood-base-black-black-muuto-5000x5000-hi-res.webp', 'other', NOW(), NOW() FROM brands b WHERE b.slug='muuto' ON CONFLICT DO NOTHING;
INSERT INTO products (name, slug, brand_id, description, dimensions, materials, source_url, image_url, category, created_at, updated_at) SELECT 'Cluster Canopy', 'cluster-canopy', b.id, 'Cluster Canopy offers a refined foundation for creating expansive pendant lighting compositions using Muuto’s smaller lamps, including E27, Rime, Ambit, and Top. Designed to support both geometric and more organic arrangements, it enables expressive lighting landscapes while maintaining a clean and balanced ceiling presence. Available with 7 or 19 holes, the canopy allows for varied configurations. Color: White Old item no.: 44705 New item no.: CLUCPY4401 Height: 4,70 cm / 1.85 in Diameter: 44,00 cm / 17.32 in Colli: 1 Download product fact sheet: -                                     Product fact sheet', 'Height: 4,70 cm; Diameter: 44,00 cm', 'The canopy is made from injection-moulded ABS with steel brackets. The cross bracket is fitted with a hinge, allowing the canopy to be opened, adjusted, and closed to facilitate installation and adjustment of the lamp lengths.  The canopy is equipped with a strain relief and a connecting terminal. The cord is included. For the US variant, the canopy is made using 50% post-consumer recycled ABS.', 'https://www.muuto.com/product/Cluster-Canopy/', 'https://cdn.occtoo-media.com/4d81f22f-2795-41f2-b8bf-15e9abf03890/c755b830-9ba1-54cf-bb09-e8cb917dfe52/Cluster-canopy-44-white-muuto-5000x5000-hi-res.webp', 'other', NOW(), NOW() FROM brands b WHERE b.slug='muuto' ON CONFLICT DO NOTHING;
INSERT INTO products (name, slug, brand_id, description, dimensions, materials, source_url, image_url, category, created_at, updated_at) SELECT 'Coltre Modular Sofa 2-Seater Configurations', 'coltre-modular-sofa-2-seater-configurations', b.id, 'Named after the Italian word “Coltre”, meaning blanket, the design refers to a soft, padded layer resting gently over a defined surface. A quilted textile top drapes over a structured wood frame, where parallel stitched lines create rhythm and puffed volume across the sofa and its configurations. The side profile reads like a precise slice through layered tiers, revealing its architectural character and sculptural depth. Each module can stand alone or be combined into composed, flexible arrangements, allowing configurations that range from simple compositions to more expansive layouts. Upholstery: Turf - Sand Variant: Turf / Sand Seat finish: Turf - Sand New item no.: CLT2SC1TC03 Colli: 1 Download product fact sheet: -                                     Product fact sheet', NULL, 'The frame is made from FSC™-certified (FSC-C028824) wood and is fitted with metal springs to ensure seating comfort. A foam shell, lined with non-woven fabric, is stapled to the wooden frame.  A fabric cover that encloses the entire module is removable and can be replaced if needed or refitted with zippers. It is tightly fit around the frame and has a quilted top layer on the seating surface that is softer and lived-in. The wadded filling within the quilted top layer is fixed and cannot be separ', 'https://www.muuto.com/product/Coltre-Modular-Sofa-2-Seater-Configurations/', 'https://cdn.occtoo-media.com/4d81f22f-2795-41f2-b8bf-15e9abf03890/d1b30523-cbf7-5584-aa49-c56351cd6a4a/Coltra%20Modular%20Sofa%202-seater%20Config%201_WEB_Stregtegninger_5000x5000px.webp', 'sofas', NOW(), NOW() FROM brands b WHERE b.slug='muuto' ON CONFLICT DO NOTHING;
