INSERT INTO products (name, slug, brand_id, description, dimensions, materials, source_url, image_url, category, created_at, updated_at) SELECT 'Coltre Modular Sofa Armrest Cushion', 'coltre-modular-sofa-armrest-cushion', b.id, 'Designed to complement the Coltre Sofa, the armrest cushion extends the idea of a soft blanket resting over a defined structure. Firm enough to function as a supportive armrest and soft enough to serve as a cushion, it adds comfort and flexibility to the seating experience. The removable textile cover wraps a structured interior that gives the cushion stability and weight, allowing it to be placed loosely on the sofa wherever needed. Upholstery: Turf - Sand Variant: Turf / Sand Seat finish: Turf - Sand New item no.: CLTACSTC03 Height: 17,00 cm / 6.70 in Width: 29,00 cm / 11.40 in Depth: 46,00 cm / 18.10 in Colli: 1 Download product fact sheet: -                                     Product fact sheet', 'Height: 17,00 cm; Width: 29,00 cm; Depth: 46,00 cm', 'The armrest cushion is constructed with a core of foam and wadding, combined with a wooden board at the base to provide structure and weight. The cushion is upholstered with a removable textile cover.', 'https://www.muuto.com/product/Coltre-Modular-Sofa-Armrest-Cushion/', 'https://cdn.occtoo-media.com/4d81f22f-2795-41f2-b8bf-15e9abf03890/57053c0e-f382-5e10-b114-3beeac7e9205/Coltre-modular-sofa-armrest-cushion-turf-sand-muuto-5000x5000-hi-res.png.webp', 'sofas', NOW(), NOW() FROM brands b WHERE b.slug='muuto' ON CONFLICT DO NOTHING;
