INSERT INTO products (name, slug, brand_id, description, dimensions, materials, source_url, image_url, category, created_at, updated_at) SELECT 'Coltre Modular Sofa Modules', 'coltre-modular-sofa-modules', b.id, 'Named after the Italian word “Coltre”, meaning blanket, the design refers to a soft, padded layer resting gently over a defined surface. A quilted textile top drapes over a structured wood frame, where parallel stitched lines create rhythm and puffed volume across the sofa and its configurations. The side profile reads like a precise slice through layered tiers, revealing its architectural character and sculptural depth. Each module can stand alone or be combined into composed, flexible arrangements, allowing configurations that range from simple compositions to more expansive layouts. Variant: Turf / Sand New item no.: CLTMDATC03 Height: 68,00 cm / 26.77 in Width: 90,00 cm / 35.40 in Depth: 118,00 cm / 42.50 in Seat height: 42,00 cm / 16.54 in Seat depth: 65,00 cm / 25.60 in Colli: 1 Download product fact sheet: -                                     Product fact sheet', 'Height: 68,00 cm; Width: 90,00 cm; Depth: 118,00 cm; height: 42,00 cm; depth: 65,00 cm', 'The frame is made from FSC™-certified (FSC-C028824) wood and is fitted with metal springs to ensure seating comfort. A foam shell, lined with non-woven fabric, is stapled to the wooden frame.  A fabric cover that encloses the entire module is removable and can be replaced if needed or refitted with zippers. It is tightly fit around the frame and has a quilted top layer on the seating surface that is softer and lived-in. The wadded filling within the quilted top layer is fixed and cannot be separated.  The modules stand on legs made from FSC™-certified (FSC-C028824) beech. Each module is equipp', 'https://www.muuto.com/product/Coltre-Modular-Sofa-Modules/', 'https://cdn.occtoo-media.com/4d81f22f-2795-41f2-b8bf-15e9abf03890/244136ad-8202-5269-8bb4-6f47fe387d37/Coltre-module-a-turf-sand-muuto-5000x5000-hi-res.png.webp', 'other', NOW(), NOW() FROM brands b WHERE b.slug='muuto' ON CONFLICT DO NOTHING;
INSERT INTO products (name, slug, brand_id, description, dimensions, materials, source_url, image_url, category, created_at, updated_at) SELECT 'Connect Modular Sofa 6-Seater Configurations', 'connect-modular-sofa-6-seater-configurations', b.id, 'The Connect Modular Sofa brings a modern perspective to the typology, allowing for its user to customize the sofa for their exact spatial and aesthetic needs with 14 different modules. Designed with long, elegant lines, the Connect Modular Sofa''s details of its small feet underneath for a hovering, light sentiment and pointy corners allows for the design to bring character to any space, all while complementing and enhancing its surroundings. Use the Connect Modular Sofa for a modern comfort in any workplace, lounge area or hospitality setting. New item no.: CON6SC1 Height: 74,00 cm / 29.13 in Width: 948,00 cm / 365.35 in Depth: 98,00 cm / 38.58 in Seat height: 42,00 cm / 16.54 in Seat depth: 64,00 cm / 25.20 in Download product fact sheet: -                                     Product fact sheet', 'Height: 74,00 cm; Width: 948,00 cm; Depth: 98,00 cm; Seat height: 42,00 cm; Seat depth: 64,00 cm', 'Seat and back frame are made in FSC™-certified (FSC-C028824) wood. The back frame is padded with cold foam and wadding, while the seat features zig-zag springs, felt, cold foam, and wadding. The modules are upholstered in high-quality textiles, imitation leather, or leather, with a thin layer of wadding underneath. Metal brackets are used to connect the modules.  Plastic: Plastic is a synthetic material made from various organic polymers, such as polyethylene or PVC.  Table: MDF with oak veneer ', 'https://www.muuto.com/product/Connect-Modular-Sofa-6-Seater-Configurations/', 'https://cdn.occtoo-media.com/4d81f22f-2795-41f2-b8bf-15e9abf03890/6f19682a-371b-58c2-be0f-d72ea2edafac/Oslo-2-seater-vidar-554-Muuto-5000x5000-hi-res.webp', 'sofas', NOW(), NOW() FROM brands b WHERE b.slug='muuto' ON CONFLICT DO NOTHING;
INSERT INTO products (name, slug, brand_id, description, dimensions, materials, source_url, image_url, category, created_at, updated_at) SELECT 'Contra Floor Lamp', 'contra-floor-lamp', b.id, 'The Contra Floor Lamp is designed as a striking statement piece, where balance, movement, and scale come together in a refined composition. A counterweighted mechanism allows the lamp to adjust with smooth, intuitive motion, where shifting the equilibrium directly changes how the lamp is used. Expressive, curved pipes form a soft silhouette, while the voluminous shade and diffuser create a layered, atmospheric glow. Crafted from aluminum and steel, with tactile powder-coated surfaces and brushed steel details, and a concrete base, Contra combines durable construction with carefully considered finishing. Color: Anthracite Black Variant: Anthracite Black / Anthracite Black Concrete New item no.: CRAFLR01 Height: 188,00 cm / 74.00 in Width: 256,00 cm / 100.80 in Diameter: 26,00 cm / 10.20 in Cord length: 300,00 cm / 118.10 in Colli: 1 Download product fact sheet: -                                     Product fact sheet', 'Height: 188,00 cm; Width: 256,00 cm; Diameter: 26,00 cm; length: 300,00 cm', 'The lamp arm is made from powder-coated steel. The lamp shade is made from spun, powder-coated aluminum. The diffuser is made from injection-moulded PMMA. The base is made from colored cement.  The light source is a user-replaceable LED with stepless dimming. It provides 750 lumens at 100% brightness. Lumen maintenance (80%) exceeds 35,000 hours. The color temperature is 2700K with a CRI above 90.  The lamp arm allows for smooth height adjustment by a subtle twist of the counterweight, ranging from approximately 260 cm to 30 cm from the ground. The base allows for sideways rotation, enabling m', 'https://www.muuto.com/product/Contra-Floor-Lamp/', 'https://cdn.occtoo-media.com/4d81f22f-2795-41f2-b8bf-15e9abf03890/4e0396dc-c8ca-54ab-a512-fd3786ad60de/Contra-floor-lamp-anthracite-black-concrete-muuto-5000x5000-hi-res.webp', 'other', NOW(), NOW() FROM brands b WHERE b.slug='muuto' ON CONFLICT DO NOTHING;
INSERT INTO products (name, slug, brand_id, description, dimensions, materials, source_url, image_url, category, created_at, updated_at) SELECT 'E27 Pendant Cluster', 'e27-pendant-cluster', b.id, 'The E27 Cluster Pendant transforms the simplicity of the E27 Pendant Lamp into a striking multi-light composition. Combining industrial character with Scandinavian simplicity, the exposed LED bulbs and silicone rubber sockets create a graphic and contemporary expression. Suspended together in a balanced arrangement, the lamps form a distinctive lighting feature suited for any space. Color: White Variant: White / Beige Green New item no.: E27CLB0101 Diameter: 76,00 cm / 29.20 in Colli: 1 Download product fact sheet: -                                     Product fact sheet', 'Diameter: 76,00 cm', 'The E27 Pendant Lamp is pressed in vulcanized silicone rubber under high temperature. Inside plastic socket and PVC cord is assembled by hand.  The silicone rubber is made from silicone elastomers, created with extensive flexibility, durability and strength.  The canopy is made from injection-moulded ABS with steel brackets. The cross bracket is fitted with a hinge, allowing the canopy to be opened, adjusted, and closed to facilitate installation and adjustment of the lamp lengths.  The canopy i', 'https://www.muuto.com/product/E27-Pendant-Cluster/', 'https://cdn.occtoo-media.com/4d81f22f-2795-41f2-b8bf-15e9abf03890/366cf975-4299-513e-9b7b-a19602b75985/E27-Cluster-12-Layout-1-Flat-Beige-Green-org.webp', 'lighting', NOW(), NOW() FROM brands b WHERE b.slug='muuto' ON CONFLICT DO NOTHING;
INSERT INTO products (name, slug, brand_id, description, dimensions, materials, source_url, image_url, category, created_at, updated_at) SELECT 'Fiber Soft Lounge Chair Tube Base', 'fiber-soft-lounge-chair-tube-base', b.id, 'Developed from the Fiber Lounge Chair’s soft, embracing curves that provide generous comfort within a compact footprint, the Fiber Soft Lounge Chair retains its refined, space-conscious character while introducing a more cushioned expression. The upholstery enhances the gentle form with added depth and tactility, creating a warm, inviting seat. The chair’s shell is made from 100% recycled plastic, supported by a slender tube base that lends a light expression. Variant: Clay 12,Anthracite Black,Plastic Base color: Anthracite Black Base material: Tube Base Seat finish: Full Upholstery New item no.: FISLOTUUCD12011 Height: 74,40 cm / 29.30 in Width: 60,00 cm / 23.60 in Depth: 69,00 cm / 27.20 in Seat height: 41,00 cm / 16.10 in Seat depth: 49,00 cm / 19.30 in Colli: 1 Download product fact sheet: -                                     Product fact sheet', 'Height: 74,40 cm; Width: 60,00 cm; Depth: 69,00 cm; height: 41,00 cm; depth: 49,00 cm', 'The shell is made using 100% recycled plastic reinforced with strength-improving additives and mixed with up to 25% FSC™- certified (FSC-C028824) wood fibers. The recycled plastic comes from post-industrial waste. The shell is upholstered with several layers of foam and wadding, then finished with upholstery in textile, imitation leather, or leather—the leather is sourced from selected premium suppliers. Tube base in powder-coated steel. Plastic glides included. Felt glides are available as a spare part.', 'https://www.muuto.com/product/Fiber-Soft-Lounge-Chair-Tube-Base/', 'https://cdn.occtoo-media.com/4d81f22f-2795-41f2-b8bf-15e9abf03890/4b303763-3671-5679-948e-716e8fcc054e/Fiber-soft-lounge-chair-tube-base-dusty-green-delta-26-muuto-5000x5000-hi-res.webp?format=medium', 'other', NOW(), NOW() FROM brands b WHERE b.slug='muuto' ON CONFLICT DO NOTHING;
INSERT INTO products (name, slug, brand_id, description, dimensions, materials, source_url, image_url, category, created_at, updated_at) SELECT 'Fiber Soft Lounge Chair Wood Base', 'fiber-soft-lounge-chair-wood-base', b.id, 'Developed from the Fiber Lounge Chair’s soft, embracing curves that provide generous comfort within a compact footprint, the Fiber Soft Lounge Chair retains its refined, space-conscious character while introducing a more cushioned expression. The upholstery enhances the gentle form with added depth and tactility, creating a warm, inviting seat. The chair’s shell is made from 100% recycled plastic, supported by a wood base made from FSC™-certified (FSC-C028824) oak. New item no.: FISLOWOU Height: 74,40 cm / 29.30 in Width: 60,00 cm / 23.60 in Depth: 69,00 cm / 27.20 in Seat height: 41,00 cm / 16.10 in Seat depth: 49,00 cm / 19.30 in Download product fact sheet: -                                     Product fact sheet', 'Height: 74,40 cm; Width: 60,00 cm; Depth: 69,00 cm; height: 41,00 cm; depth: 49,00 cm', 'The shell is made using 100% recycled plastic reinforced with strength-improving additives and mixed with up to 25% FSC™- certified (FSC-C028824) wood fibers. The recycled plastic comes from post-industrial waste. The shell is upholstered with several layers of foam and wadding, then finished with upholstery in textile, imitation leather, or leather—the leather is sourced from selected premium suppliers.  Wood base is made from FSC™-certified (FSC-C028824) oak with water-based lacquer. For Stained Dark Brown version only: Please note that slight color variations can occur due to the inherent c', 'https://www.muuto.com/product/Fiber-Soft-Lounge-Chair-Wood-Base/', 'https://cdn.occtoo-media.com/4d81f22f-2795-41f2-b8bf-15e9abf03890/9817168c-2870-5e6e-bf6e-25f1a70195e2/Fiber-soft-lounge-chair-wood-base-oak-acca-231-muuto-5000x5000-hi-res.webp?format=medium', 'other', NOW(), NOW() FROM brands b WHERE b.slug='muuto' ON CONFLICT DO NOTHING;
INSERT INTO products (name, slug, brand_id, description, dimensions, materials, source_url, image_url, category, created_at, updated_at) SELECT 'Folded Trolley', 'folded-trolley', b.id, 'The Folded Trolley translates the visual language of folded paper into durable steel, giving the design a contemporary and functional character. Defined by its clean folds and subtle detailing, the trolley offers a practical storage solution for both residential and professional settings. A display pocket at the back offers space for books or objects, complemented by a drawer in the closed version, which can be fitted with a lock. Designed for flexibility, the trolley comes with both glides and wheels for easy movement and placement. New item no.: FLDTRO61DR0101 Height: 61,50 cm Colli: 1 Download product fact sheet: -                                     Product fact sheet', 'Height: 61,50 cm', 'The product is made from a bent sheet of steel with either a matte or high-gloss powder-coated finish. The components are laser cut and formed.  The product is supplied with both castors and adjustable glides in black plastic. The castors are made from 100% post-industrial recycled plastic. All stated height measurements are based on the use of castors.  Versions with a drawer include a steel drawer with soft-close hinges. Versions with a lock are fitted with a black anodized lock with keys.  Glides, castors, and drawer can be disassembled.', 'https://www.muuto.com/product/Folded-Trolley/', 'https://cdn.occtoo-media.com/4d81f22f-2795-41f2-b8bf-15e9abf03890/58b0b702-a518-5661-82e2-ea91e695db44/Folded-trolley-h62-drawer-black-muuto-5000x5000-hi-res.webp', 'other', NOW(), NOW() FROM brands b WHERE b.slug='muuto' ON CONFLICT DO NOTHING;
INSERT INTO products (name, slug, brand_id, description, dimensions, materials, source_url, image_url, category, created_at, updated_at) SELECT 'Relevo Quattro Rug', 'relevo-quattro-rug', b.id, 'Relevo Quattro is a soft rug defined by a sculptural surface and a clear rectangular form with four distinct corners. Crafted from tufted wool trimmed at different levels, the design forms a precise graphic pattern where fine lines create nuanced shadow play across the surface. Available in the same color palette as the Relevo collection, Quattro introduces a more architectural and graphic dimension while preserving the tactile depth of the series. Relevo Rug Colors: Burnt Orange Old item no.: 60603 New item no.: RLVRQU240A01 Length: 240,00 cm / 94.50 in Width: 170,00 cm / 66.90 in Colli: 1 Download product fact sheet: -                                     Product fact sheet', 'Length: 240,00 cm; Width: 170,00 cm', 'Made from 100% New Zealand wool and hand-tufted in India. The backing is made from 100% cotton and is applied with synthetic latex, ensuring the rug lies smoothly on the floor. Relevo Quattro does not require a rug pad due to its weight.  Shedding is a natural occurrence and will decrease over time. The color may vary depending on the wool’s natural base color. All rugs have a size tolerance of +/- 2%, meaning the dimensions may vary within this range.', 'https://www.muuto.com/product/Relevo-Quattro-Rug/', 'https://cdn.occtoo-media.com/4d81f22f-2795-41f2-b8bf-15e9abf03890/3ac9cbf0-494b-5caa-aec8-6d7d899de91f/Relevo-quattro-rug-170x240-burnt-orange-muuto-5000x5000-hi-res.webp', 'accessories', NOW(), NOW() FROM brands b WHERE b.slug='muuto' ON CONFLICT DO NOTHING;
INSERT INTO products (name, slug, brand_id, description, dimensions, materials, source_url, image_url, category, created_at, updated_at) SELECT 'Rest Corner Sofa', 'rest-corner-sofa', b.id, 'Rest Corner Sofa expands the Rest series into a generous corner configuration that enhances both comfort and spatial presence. Deep seating, broad armrests, and subtle folded details shape its soft, architectural silhouette. Available with wood, metal, or chrome bases, it offers a balanced expression suited for residential and refined contract interiors. New item no.: RESCR Height: 72,00 cm / 28.10 in Width: 301,00 cm / 117.60 in Depth: 301,00 cm / 117.60 in Seat height: 42,00 cm / 16.40 in Seat depth: 60,00 cm / 23.40 in Length between legs: 74,00 cm / 28.90 in Download product fact sheet: -                                     Product fact sheet', 'Height: 72,00 cm; Width: 301,00 cm; Depth: 301,00 cm; height: 42,00 cm; depth: 60,00 cm', 'The legs are made from powder-coated or chromed steel or made from FSC™-certified (FSC-C028824) solid oak.  The frame is constructed from plywood and High-Density Fiberboard (HDF) made from FSC™-certified (FSC-C028824) wood, and is fitted with zig-zag springs, foam, and wadding. The product is upholstered in high-quality textile.  The EU/US version is made with standard and high-resilience polyurethane foam. The UK version is made with standard fire-retardant polyurethane foam and combustion-modified high-resilience foam.', 'https://www.muuto.com/product/Rest-Corner-Sofa/', 'https://cdn.occtoo-media.com/4d81f22f-2795-41f2-b8bf-15e9abf03890/10aa639f-c835-53b5-861d-ae9fec276b71/Rest-corner-sofa-metal-base-black-hearth-6-muuto-5000x5000-hi-res.webp?format=medium', 'other', NOW(), NOW() FROM brands b WHERE b.slug='muuto' ON CONFLICT DO NOTHING;
INSERT INTO products (name, slug, brand_id, description, dimensions, materials, source_url, image_url, category, created_at, updated_at) SELECT 'Rest Lounge Chair', 'rest-lounge-chair', b.id, 'Rest Lounge Chair brings generous comfort into a refined lounge format. Broad armrests, a deep seat, and subtle folded details create an inviting silhouette with a soft interior feel. Available with wood, metal, or chrome bases, it offers versatile expressions while maintaining the calm, modern identity of the Rest series. Upholstery: Hearth 6 Variant: Hearth 6 / Black Base color: Black Metal Seat finish: Hearth 6 New item no.: RESLOUHB0602 Height: 72,00 cm / 28.10 in Width: 105,00 cm / 41.00 in Depth: 88,00 cm / 34.40 in Seat height: 42,00 cm / 16.40 in Seat depth: 54,00 cm / 21.10 in Length between legs: 59,00 cm / 22.90 in Colli: 1 Download product fact sheet: -                                     Product fact sheet', 'Height: 72,00 cm; Width: 105,00 cm; Depth: 88,00 cm; height: 42,00 cm; depth: 54,00 cm', 'The legs are made from powder-coated or chromed steel or made from FSC™-certified (FSC-C028824) solid oak.  The frame is constructed from plywood and High-Density Fiberboard (HDF) made from FSC™-certified (FSC-C028824) wood, and is fitted with zig-zag springs, foam, and wadding. The product is upholstered in high-quality textile.  The EU/US version is made with standard and high-resilience polyurethane foam. The UK version is made with standard fire-retardant polyurethane foam and combustion-mod', 'https://www.muuto.com/product/Rest-Lounge-Chair/', 'https://cdn.occtoo-media.com/4d81f22f-2795-41f2-b8bf-15e9abf03890/a8df7545-8983-50eb-a050-38acd4199b0f/rest-lounge-chair-hearth-06-contra-floor-lamp-folded-trolley-dark-beige-green-relevo-quattro-taupe-HI-RES.webp', 'sofas', NOW(), NOW() FROM brands b WHERE b.slug='muuto' ON CONFLICT DO NOTHING;
INSERT INTO products (name, slug, brand_id, description, dimensions, materials, source_url, image_url, category, created_at, updated_at) SELECT 'Rest Sofa 3-Seater', 'rest-sofa-3-seater', b.id, 'Rest 3-Seater Sofa combines generous proportions with a calm, architectural expression. Deep seating, broad armrests, and subtle folded details create an inviting silhouette that balances sculptural form with soft comfort. Available with wood, metal, or chrome bases, it offers versatile expressions suited for both residential interiors and refined contract environments. Upholstery: Hearth 6 Variant: Hearth 6 / Black Base color: Black Metal Seat finish: Hearth 6 New item no.: RES3SHB0602 Height: 72,00 cm / 28.34 in Width: 222,00 cm / 86.70 in Depth: 101,00 cm / 39.50 in Seat height: 42,00 cm / 16.54 in Seat depth: 60,00 cm / 23.62 in Colli: 1 Download product fact sheet: -                                     Product fact sheet', 'Height: 72,00 cm; Width: 222,00 cm; Depth: 101,00 cm; height: 42,00 cm; depth: 60,00 cm', 'The legs are made from powder-coated or chromed steel or made from FSC™-certified (FSC-C028824) solid oak.  The frame is constructed from plywood and High-Density Fiberboard (HDF) made from FSC™-certified (FSC-C028824) wood, and is fitted with zig-zag springs, foam, and wadding. The product is upholstered in high-quality textile.  The EU/US version is made with standard and high-resilience polyurethane foam. The UK version is made with standard fire-retardant polyurethane foam and combustion-mod', 'https://www.muuto.com/product/Rest-Sofa-3-Seater/', 'https://cdn.occtoo-media.com/4d81f22f-2795-41f2-b8bf-15e9abf03890/f97d84c2-1420-50e6-898b-581aa80c1853/Rest-sofa-3-seater-metal-base-black-hearth-6-muuto-5000x5000-hi-res.webp', 'sofas', NOW(), NOW() FROM brands b WHERE b.slug='muuto' ON CONFLICT DO NOTHING;
INSERT INTO products (name, slug, brand_id, description, dimensions, materials, source_url, image_url, category, created_at, updated_at) SELECT 'Rest Sofa Chaise Longue', 'rest-sofa-chaise-longue', b.id, 'Rest Sofa Chaise Longue extends the generous comfort of the Rest series with an elongated section designed for relaxed lounging. Broad armrests, a deep cushion, and subtle folded details shape its soft, architectural silhouette. Available in left and right versions with wood, metal, or chrome bases, offering versatile expressions for residential and contract interiors. New item no.: RESCEL Height: 72,00 cm / 28.10 in Width: 312,50 cm / 122.10 in Depth: 166,00 cm / 64.80 in Seat height: 42,00 cm / 16.40 in Seat depth: 129,50 cm / 50.60 in Download product fact sheet: -                                     Product fact sheet', 'Height: 72,00 cm; Width: 312,50 cm; Depth: 166,00 cm; height: 42,00 cm; depth: 129,50 cm', 'The legs are made from powder-coated or chromed steel or made from FSC™-certified (FSC-C028824) solid oak.  The frame is constructed from plywood and High-Density Fiberboard (HDF) made from FSC™-certified (FSC-C028824) wood, and is fitted with zig-zag springs, foam, and wadding. The product is upholstered in high-quality textile.  The EU/US version is made with standard and high-resilience polyurethane foam. The UK version is made with standard fire-retardant polyurethane foam and combustion-modified high-resilience foam.', 'https://www.muuto.com/product/Rest-Sofa-Chaise-Longue/', 'https://cdn.occtoo-media.com/4d81f22f-2795-41f2-b8bf-15e9abf03890/7284a554-fa35-5e79-ac0a-e33ee0d443ea/Rest-sofa-chaise-longue-left-wood-base-oak-ecriture-710-muuto-5000x5000-hi-res.webp?format=medium', 'other', NOW(), NOW() FROM brands b WHERE b.slug='muuto' ON CONFLICT DO NOTHING;
INSERT INTO products (name, slug, brand_id, description, dimensions, materials, source_url, image_url, category, created_at, updated_at) SELECT 'Rime Pendant Cluster', 'rime-pendant-cluster', b.id, 'The Rime Cluster Pendant brings together multiple Rime Pendant Lamps to form a refined lighting composition with a soft, atmospheric glow. Each lamp features semi-transparent, sandblasted glass and a distinctive acorn-inspired shape, paired with a powder-coated top and matching tube and cord. Suspended in a balanced cluster, the lamps create an elegant focal point that adds depth and sophistication to any space. Color: White Variant: White / Black New item no.: RIMCL12B0101 Diameter: 76,00 cm / 29.20 in Colli: 1 Download product fact sheet: -                                     Product fact sheet', 'Diameter: 76,00 cm', 'The shade is made from mouth-blown glass with a sandblasted finish. The top piece and pendant tube are made from powder-coated aluminum. The cord is made from PVC.  The canopy is made from injection-moulded ABS with steel brackets. The cross bracket is fitted with a hinge, allowing the canopy to be opened, adjusted, and closed to facilitate installation and adjustment of the lamp lengths.  The canopy is equipped with a strain relief and a connecting terminal. The cord is included. For the US variant, the canopy is made using 50% post-consumer recycled ABS.', 'https://www.muuto.com/product/Rime-Pendant-Cluster/', 'https://cdn.occtoo-media.com/4d81f22f-2795-41f2-b8bf-15e9abf03890/9738fcd0-05c2-5292-aac2-a94d75eac0fd/Rime-Cluster-12-O12-Layout-1-Flat-Black-org.webp', 'other', NOW(), NOW() FROM brands b WHERE b.slug='muuto' ON CONFLICT DO NOTHING;
INSERT INTO products (name, slug, brand_id, description, dimensions, materials, source_url, image_url, category, created_at, updated_at) SELECT 'Settle Ottoman', 'settle-ottoman', b.id, 'The Settle Sofa invites you to settle into its comfort, providing an ideal setting for enjoying the outdoors all day. Its airy steel frame, complete with visible belts and intricate details, enhances its visual allure from all angles. Settle’s steel frame is galvanized, primed, and powder-coated, ensuring corrosion resistance for long-lasting use. The plush cushions, made with quick-dry foam and durable outdoor textiles, offer fast-drying resilience in rain showers and year-round durability when used with an outdoor cover. The ottoman extends the modular system, allowing flexible sofa configurations while providing a versatile surface for resting legs or creating additional seating. New item no.: STTOTT Height: 42,00 cm / 16.54 in Width: 69,00 cm / 27.17 in Depth: 55,00 cm / 21.65 in Download product fact sheet: -                                     Product fact sheet', 'Height: 42,00 cm; Width: 69,00 cm; Depth: 55,00 cm', 'Seat cushion: The seat cushion is constructed from multiple layers of outdoor-suited foam to provide enhanced support and comfort. The foam is wrapped in wadding and an inner lining, and finished with outdoor-suited upholstery. An integrated anti-slip feature helps keep the cushion securely in place.  Frame and webbing: The frame is made from bent steel tubes, rods, and plates that are electro-galvanized, primed, and powder-coated. The webbing is made from 71% polypropylene (PP) and 29% natural rubber.  The product is designed for disassembly for the main components (frame, armrests, cushions,', 'https://www.muuto.com/product/Settle-Otoman/', 'https://cdn.occtoo-media.com/4d81f22f-2795-41f2-b8bf-15e9abf03890/d92cae3c-b9df-5976-9f90-6979c9920aeb/Settle%20-%20Ottoman_WEB_Stregtegninger_5000x5000px.webp', 'other', NOW(), NOW() FROM brands b WHERE b.slug='muuto' ON CONFLICT DO NOTHING;
INSERT INTO products (name, slug, brand_id, description, dimensions, materials, source_url, image_url, category, created_at, updated_at) SELECT 'Settle Sofa 3-Seater Configurations', 'settle-sofa-3-seater-configurations', b.id, 'The Settle Sofa invites you to settle into its comfort, providing an ideal setting for enjoying the outdoors all day. Its airy steel frame, complete with visible belts and intricate details, enhances its visual allure from all angles. Settle’s steel frame is galvanized, primed, and powder-coated, ensuring corrosion resistance for long-lasting use. The plush cushions, made with quick-dry foam and durable outdoor textiles, offer fast-drying resilience in rain showers and year-round durability when used with an outdoor cover. New item no.: STT3SC1 Height: 73,00 cm / 28.75 in Width: 218,50 cm / 86.02 in Depth: 141,00 cm / 55.51 in Seat height: 44,00 cm / 17.32 in Seat depth: 55,00 cm / 21.65 in Download product fact sheet: -                                     Product fact sheet', 'Height: 73,00 cm; Width: 218,50 cm; Depth: 141,00 cm; height: 44,00 cm; depth: 55,00 cm', 'Back cushion: The back cushion consists of a single outdoor-suited foam core wrapped in wadding and enclosed in an inner lining. It is finished with outdoor-suited upholstery. Loose cushions for added back support can be purchased separately.  Seat cushion: The seat cushion is constructed from multiple layers of outdoor-suited foam to provide enhanced support and comfort. The foam is wrapped in wadding and an inner lining, and finished with outdoor-suited upholstery. An integrated anti-slip feat', 'https://www.muuto.com/product/Settle-Sofa-3-Seater-Configurations/', 'https://cdn.occtoo-media.com/4d81f22f-2795-41f2-b8bf-15e9abf03890/59731c1a-31c2-53c4-b3fe-101884ba9130/Settle-lounge-bed-laze-1-grey-angle-muuto-5000x5000.webp?format=medium', 'sofas', NOW(), NOW() FROM brands b WHERE b.slug='muuto' ON CONFLICT DO NOTHING;
