INSERT INTO products (name, slug, brand_id, description, dimensions, materials, source_url, image_url, category, created_at, updated_at) SELECT 'Settle Sofa w. Single Armrest 2-Seater', 'settle-sofa-w-single-armrest-2-seater', b.id, NULL, 'Height: 73,00 cm; Width: 144,00 cm; Depth: 84,00 cm; Seat height: 44,00 cm; Seat depth: 55,00 cm', 'Back cushion: The back cushion consists of a single outdoor-suited foam core wrapped in wadding and enclosed in an inner lining. It is finished with outdoor-suited upholstery. Loose cushions for added back support can be purchased separately. Seat cushion: The seat cushion is constructed from multiple layers of outdoor-suited foam to provide enhanced support and comfort. The foam is wrapped in wadding and an inner lining, and finished with outdoor-suited upholstery. An integrated anti-slip featu', 'https://www.muuto.com/product/Settle-Sofa-Single-Armrest-2-Seater/', 'https://cdn.occtoo-media.com/4d81f22f-2795-41f2-b8bf-15e9abf03890/59731c1a-31c2-53c4-b3fe-101884ba9130/Settle-lounge-bed-laze-1-grey-angle-muuto-5000x5000.webp', 'sofas', NOW(), NOW() FROM brands b WHERE b.slug='muuto' ON CONFLICT DO NOTHING;
INSERT INTO products (name, slug, brand_id, description, dimensions, materials, source_url, image_url, category, created_at, updated_at) SELECT 'Top Pendant Cluster', 'top-pendant-cluster', b.id, 'The Top Cluster Pendant transforms the simple geometry of the Top Pendant into a striking multi-light installation. Defined by its cone-shaped silhouette and distinctive rolled hem in spun steel, each lamp offers a clean, graphic expression. Arranged together in a balanced cluster, the pendants create a contemporary chandelier-like composition that adds rhythm and visual presence to any space. Ambit Lamp Color: Black Color: White Variant: White / Dark Green New item no.: TOPCL21A0101 Diameter: 76,00 cm / 29.20 in Colli: 1 Download product fact sheet: -                                     Product fact sheet', 'Diameter: 76,00 cm', 'The shade is made from spun steel with a high-gloss wet-painted finish. The socket is made from nylon. A GX53 light bulb is included. The canopy is made from injection-moulded ABS with steel brackets. The cross bracket is fitted with a hinge, allowing the canopy to be opened, adjusted, and closed to facilitate installation and adjustment of the lamp lengths.  The canopy is equipped with a strain relief and a connecting terminal. The cord is included. For the US variant, the canopy is made using ', 'https://www.muuto.com/product/Top-Pendant-Cluster/', 'https://cdn.occtoo-media.com/4d81f22f-2795-41f2-b8bf-15e9abf03890/01a59cc4-09bf-5a9a-847a-94e0214b16da/Top-Cluster-6-Layout-1-Ring-Dark-Green-org.webp', 'lighting', NOW(), NOW() FROM brands b WHERE b.slug='muuto' ON CONFLICT DO NOTHING;
INSERT INTO products (name, slug, brand_id, description, dimensions, materials, source_url, image_url, category, created_at, updated_at) SELECT 'Verso Rug', 'verso-rug', b.id, 'Verso Rug explores simplicity through technique, translating the logic of a plain weave into a balanced and tactile design. Crafted from 100% wool, the rug features an equal interplay between warp and weft, creating a surface that appears identical from both sides. Hand-twisted fringes on all four edges frame the rug, highlighting the craftsmanship behind the piece while allowing it to be positioned freely within a space. The composition of two colors—meeting and blending across the surface—adds subtle depth, bringing a sense of rhythm and balance to any room. Old item no.: 60800 New item no.: VERRUG240A01 Length: 258,00 cm / 101.57 in Width: 258,00 cm / 101.57 in Colli: 1 Download product fact sheet: -                                     Product fact sheet', 'Length: 258,00 cm; Width: 258,00 cm', 'Made from 100% Responsible Wool Standard certified New Zealand wool. A rug pad underneath is recommended to keep the rug in place.  The color may vary due to the wool’s natural base color. All rugs have a size tolerance of +/- 2%, meaning the dimensions may vary within this range.', 'https://www.muuto.com/product/Verso-Rug/', 'https://cdn.occtoo-media.com/4d81f22f-2795-41f2-b8bf-15e9abf03890/9ce63ef4-a0aa-565c-aaf5-c292ba527860/Verso-rug-249x249-cool-grey-dark-brown-muuto-5000x5000-hi-res.webp', 'other', NOW(), NOW() FROM brands b WHERE b.slug='muuto' ON CONFLICT DO NOTHING;

